1: /**
2:  * pdfHelper.js - Utilitas untuk Ekstraksi Teks dari File PDF & Folder
3:  * Menggunakan library 'pdf-parse' untuk membaca dokumen secara asinkron.
4:  */
5: 
6: const fs = require('fs');
7: const path = require('path');
8: const pdf = require('pdf-parse');
9: 
10: /**
11:  * Membaca file PDF dari path lokal dan mengekstrak semua konten teksnya.
12:  * @param {string} filePath - Path ke file PDF (misal: './materi_pdf/modul_asuransi.pdf')
13:  * @returns {Promise<string>} - Konten teks hasil ekstraksi
14:  */
15: async function extractTextFromPDF(filePath) {
16:   try {
17:     if (!fs.existsSync(filePath)) {
18:       throw new Error(`File tidak ditemukan di path: ${filePath}`);
19:     }
20: 
21:     const dataBuffer = fs.readFileSync(filePath);
22:     const data = await pdf(dataBuffer);
23:     return data.text;
24:   } catch (error) {
25:     console.error(`\n[PDF Error] Gagal membaca file ${path.basename(filePath)}: ${error.message}`);
26:     return "";
27:   }
28: }
29: 
30: /**
31:  * Membaca semua file PDF di dalam sebuah folder dan menggabungkan teksnya.
32:  * @param {string} dirPath - Path ke folder berisi file-file PDF (misal: './materi_pdf')
33:  * @returns {Promise<{text: string, count: number}>} - Teks gabungan dan jumlah file yang dibaca
34:  */
35: async function extractTextFromFolder(dirPath) {
36:   try {
37:     if (!fs.existsSync(dirPath)) {
38:       // Jika folder tidak ada, buat folder baru
39:       fs.mkdirSync(dirPath, { recursive: true });
40:       return { text: "", count: 0 };
41:     }
42: 
43:     const files = fs.readdirSync(dirPath);
44:     const pdfFiles = files.filter(file => path.extname(file).toLowerCase() === '.pdf');
45: 
46:     if (pdfFiles.length === 0) {
47:       return { text: "", count: 0 };
48:     }
49: 
50:     let combinedText = "";
51:     let processedCount = 0;
52: 
53:     for (const file of pdfFiles) {
54:       const filePath = path.join(dirPath, file);
55:       const text = await extractTextFromPDF(filePath);
56:       
57:       if (text && text.trim().length > 0) {
58:         combinedText += `\n\n--- DOKUMEN: ${file.toUpperCase()} ---\n`;
59:         combinedText += text;
60:         combinedText += `\n--- AKHIR DOKUMEN: ${file.toUpperCase()} ---\n`;
61:         processedCount++;
62:       }
63:     }
64: 
65:     return { text: combinedText, count: processedCount };
66:   } catch (error) {
67:     console.error(`\n[PDF Directory Error] Gagal memproses folder PDF: ${error.message}`);
68:     return { text: "", count: 0 };
69:   }
70: }
